    .replace(/\[\.{3}.+\]/, "*")
    .replace(/\[(.+)\]/, ":$1")
    .replace(/^\//, "")
    .replace(/\/$/, "");
}
// 递归遍历 `pages` 目录中的文件并生成文件路径到模块类型映射的辅助函数。
function generateFilePathToModuleTypeMapping(dir: string) {
  // 读取目录的内容
  const files = fs.readdirSync(dir);
  // 循环遍历目录中的文件
  for (const file of files) {
    // 获取完整的文件路径
    const filePath = path.join(dir, file);
    // 检查文件是否为目录
    if (fs.lstatSync(filePath).isDirectory()) {
      // 如果是目录，则递归调用此函数以处理目录中的文件
      generateFilePathToModuleTypeMapping(filePath);
    } else {
      // 如果是文件，则检查它是否为 TypeScript 文件
      if (filePath.endsWith(".tsx")) {
        // 如果是 TypeScript 文件，则导入模块并获取默认导出的类型
        const module = require(filePath);
        const moduleType = typeof module.default;
        // 将文件路径转换为扁平文件路径
        const flatFilePath = convertFilePathToFlatFilePath(filePath);
        // 使用扁平文件路径作为键，模块类型作为值向映射中添加条目
        filePathToModuleType[flatFilePath] = moduleType;
      }
    }
  }
}
// 开始递归处理 `pages` 目录中的文件
generateFilePathToModuleTypeMapping("./pages");
// 打印 map 对象
console.log(filePathToModuleType);
```
此脚本使用 `fs` 模块读取 `pages` 目录中的文件，使用 `path` 模块连接文件路径。它还使用 `require` 函数导入模块并获取默认导出的类型。
该脚本生成一个 map 对象，用于存储文件路径到模块类型的映射，并将 map 对象打印到控制台。您可以使用此 map 对象生成 TypeScript 声明文件。

为了确保使用tRPC在服务器上获取您的查询，您可以使用tRPC提供的“ssr”选项。此选项启用服务器端渲染，这意味着查询在服务器上获取而不是在客户端上获取。

要启用“ssr”，您需要执行以下操作：
1. 在您的项目中安装“next-plugin-trpc”或“@trpc/react/ssr”包。
2. 从“@trpc/react/ssr”导入“ssr”函数或使用“next-plugin-trpc”提供的“trpcLink”。
3. 使用“ssr”函数或“next-plugin-trpc”的“withTRPC” HOC包装您的组件。
4. 使用“useQuery”钩子从服务器获取数据。

以下是如何使用“ssr”函数的示例：
```jsx
import { ssr } from '@trpc/react/ssr';
import { useQuery } from '@trpc/react';
import { AppRouter } from '../trpc/[trpc]';
function MyComponent() {
  const { data } = useQuery(['myQuery']);
  return <div>{data}</div>;
}
export default ssr(() => ({
  query: 'myQuery',
}))(MyComponent);
```
在此示例中，“ssr”函数包装了“MyComponent”，并指定需要在服务器上获取的“query”。当组件在服务器上呈现时，tRPC将在服务器上获取“myQuery”并将结果作为服务器响应的一部分返回。当组件在客户端上呈现时，数据已经获取，组件可以使用数据进行水合。

在C#中，枚举（或“enum”）是一种表示一组命名值的值类型。枚举对于定义具有特定基础类型（例如整数或字符串）的一组命名常量非常有用。通过为代码中使用的特定值赋予名称，它们可以使您的代码更易读和可维护。
以下是C#中枚举的示例：

```
enum Color { Red, Green, Blue }
```

在此示例中，枚举“Color”有三个值：“Red”，“Green”和“Blue”。这些值的基础类型为“int”，默认情况下，“Red”为0，“Green”为1，“Blue”为2。您还可以使用“：”运算符指定基础类型。
以下是具有自定义基础类型和值的枚举示例：

```
enum Color : byte { Red = 1, Green = 2, Blue = 3 }
```

然后，您可以像这样在代码中使用枚举值：

```
Color c = Color.Red;
```

枚举也可以用于switch语句，这使您可以编写更易读的代码：

```
switch (c)
{
    case Color.Red:
        Console.WriteLine("颜色是红色的。");
        break;
    case Color.Green:
        Console.WriteLine("颜色是绿色的。");
        break;
    case Color.Blue:
        Console.WriteLine("颜色是蓝色的。");
        break;
}
```

您还可以使用Enum.Parse()方法将字符串转换为枚举值，以及使用Enum.ToString()方法将枚举值转换为字符串。

