当然，这里有两个C程序，它们使用命名管道实现了双向（全双工）通信：
**程序1：sender.c**
```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <string.h>
#define FIFO_NAME "myfifo"
int main()
{
    int fd;
    char *message = "Hello, receiver!";
    mkfifo(FIFO_NAME, 0666);
    fd = open(FIFO_NAME, O_WRONLY);
    write(fd, message, strlen(message) + 1);
    printf("发送者发送消息：%s\n", message);
    close(fd);
    fd = open(FIFO_NAME, O_RDONLY);
    char received_message[100];
    read(fd, received_message, sizeof(received_message));
    printf("发送者接收到消息：%s\n", received_message);
    close(fd);
    unlink(FIFO_NAME);
    return 0;
}
```
**程序2：receiver.c**
```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
