这是一个基于您的要求生成JSON对象的JavaScript函数：
```javascript
function generateTrials(numTrials, imagesPerTrial, targetDistractorRatio, allImages) {
  function getRandomCoordinate() {
    return Math.random() * (1 - 0.15);
  }
  function isOverlap(image1, image2) {
    return (
      Math.abs(image1.x - image2.x) < 0.15 &&
      Math.abs(image1.y - image2.y) < 0.15
    );
  }
  function getRandomImage(type) {
    const targetImages = allImages.slice(0, 4);
    const distractorImages = allImages.slice(4);
    if (type === 'target') {
      return targetImages[Math.floor(Math.random() * targetImages.length)];
    } else {
      return distractorImages[Math.floor(Math.random() * distractorImages.length)];
    }
  }
  let trials = [];
  for (let t = 0; t < numTrials; t++) {
    let trial = [];
    const numTargets = Math.floor(imagesPerTrial * targetDistractorRatio);
    const numDistractors = imagesPerTrial - numTargets;
    for (let i = 0; i < numTargets; i++) {
      let target = {
        x: getRandomCoordinate(),
        y: getRandomCoordinate(),
        width: 0.15,
        height: 0.15,
        type: 'target',
        fn: getRandomImage('target'),
      };
      while (trial.some((image) => isOverlap(image, target))) {
        target.x = getRandomCoordinate();
        target.y = getRandomCoordinate();
      }
      trial.push(target);
    }
    for (let i = 0; i < numDistractors; i++) {
      let distractor = {
        x: getRandomCoordinate(),
        y: getRandomCoordinate(),
        width: 0.15,
        height: 0.15,
        type: 'distractor',
        fn: getRandomImage('distractor'),
      };
      while (trial.some((image) => isOverlap(image, distractor))) {
        distractor.x = getRandomCoordinate();
        distractor.y = getRandomCoordinate();
      }
      trial.push(distractor);
    }
    trials.push(trial);
  }
  return trials;
}
