import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
public class StringListFilterAndSort {
    public static void main(String[] args) {
        List<String> stringList = Arrays.asList("apple", "banana", "cherry", "date", "elderberry", "fig");
        List<String> filteredAndSortedStringList = stringList.stream()
                .filter(s -> s.startsWith("c") || s.startsWith("e"))
                .sorted()
                .collect(Collectors.toList());
        System.out.println(filteredAndSortedStringList);
    }
}
