```javascript
import React, { useState } from "react";
function DragTable() {
  const [draggedFrom, setDraggedFrom] = useState(null);
  const [data, setData] = useState([
    { col1: "Row 1, Column 1", col2: "Row 1, Column 2", col3: "Row 1, Column 3" },
    { col1: "Row 2, Column 1", col2: "Row 2, Column 2", col3: "Row 2, Column 3" },
    { col1: "Row 3, Column 1", col2: "Row 3, Column 2", col3: "Row 3, Column 3" },
  ]);
  const handleDragStart = (e, index) => {
    setDraggedFrom(index);
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/html', null);
  };
  const handleDragOver = (e, index) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };
  const handleDrop = (e, index) => {
    e.preventDefault();
    const itemDragged = data[draggedFrom];
    const remainingItems = data.filter((item, i) => i !== draggedFrom);
    setData([
      ...remainingItems.slice(0, index),
      itemDragged,
      ...remainingItems.slice(index),
    ]);
  };
  return (
    <table>
      <thead>
        <tr>
          <th draggable="true" onDragStart={(e) => handleDragStart(e, 0)} onDragOver={(e) => handleDragOver(e, 0)} onDrop={(e) => handleDrop(e, 0)}>列1</th>
          <th draggable="true" onDragStart={(e) => handleDragStart(e, 1)} onDragOver={(e) => handleDragOver(e, 1)} onDrop={(e) => handleDrop(e, 1)}>列2</th>
          <th draggable="true" onDragStart={(e) => handleDragStart(e, 2)} onDragOver={(e) => handleDragOver(e, 2)} onDrop={(e) => handleDrop(e, 2)}>列3</th>
        </tr>
      </thead>
      <tbody>
        {data.map((row, rowIndex) => (
          <tr key={rowIndex}>
            <td>{row.col1}</td>
            <td>{row.col2}</td>
            <td>{row.col3}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}
```
在这段代码中，我们使用`useState` hook来跟踪数据状态和被拖动的列的索引。定义了`handleDragStart`、`handleDragOver`和`handleDrop`函数来处理拖放事件。
然后我们渲染表格，将`draggable`属性添加到表头单元格中，并为`onDragStart`、`onDragOver`和`onDrop`定义事件监听器。这些事件监听器调用适当的函数并将被拖动的列的索引作为参数传递。
最后，我们映射数据以渲染表格行。
