```csharp
public class CustomAuthenticationMiddleware
{
    private readonly RequestDelegate _next;
    public CustomAuthenticationMiddleware(RequestDelegate next)
    {
        _next = next;
    }
    public async Task InvokeAsync(HttpContext context)
    {
        // 检查请求标头中是否存在自定义令牌
        if (context.Request.Headers.TryGetValue("Custom-Token", out var tokenValue))
        {
            // 验证令牌并相应地设置 context.User 属性
            if (IsValidToken(tokenValue))
            {
                // 创建自定义 ClaimsPrincipal 并将其设置为 context.User
                var claims = new[] { new Claim(ClaimTypes.Name, "CustomUserName") };
                var identity = new ClaimsIdentity(claims, "Custom");
                context.User = new ClaimsPrincipal(identity);
            }
        }
        // 调用管道中的下一个中间件
        await _next(context);
    }
    private bool IsValidToken(string token)
    {
        // 在此处实现您的令牌验证逻辑
        return token == "your-valid-token";
    }
}
```
