将以下 Objective-C 代码转换为惯用的 Swift，并使用内联解包可选闭包的方式替换 TNDRCallBlockIfNotNil 宏的用法：
- (void)retrieveFacebookAccessTokenWithToken:(NSString *)token
                           currentHTTPClient:(TNDRHTTPClient *)currentHTTPClient
                                  completion:(void(^)(FBSDKAccessToken * _Nullable , NSError * _Nullable))completion
{
    NSString *mePathFormat = @"/me?access_token=%@&amp;fields=id,first_name,email,permissions,verified";
    NSString *graphAPIURLFormat = [NSString stringWithFormat:@"https://graph.facebook.com%@", mePathFormat];
    NSString *requestForFacebookUserURL = [NSString stringWithFormat:graphAPIURLFormat, token];
    [currentHTTPClient GET:requestForFacebookUserURL
                parameters:nil
                   headers:nil
                  progress:nil
                   success:^(NSURLSessionDataTask *task __unused, id responseObject) {
        FBSDKAccessToken *accessToken = nil;
        if ([responseObject isKindOfClass:[NSDictionary class]]) {
            NSDictionary *jsonData = [responseObject safeDictionary];
            TNDRFacebookPermissions *permissions = jsonData[@"permissions"] ? [[TNDRFacebookPermissions alloc] initWithDictionary:jsonData[@"permissions"]] : nil;
            accessToken = [FBSDKAccessToken tndr_facebookSDKTokenWithToken:token
                                                                    userID:jsonData[@"id"] ?: @""
                                                               permissions:[TNDRFacebookPermissions typeStringsFromPermissions:permissions.grantedPermissions]];
        }
        TNDRCallBlockIfNotNil(completion)(accessToken, nil);
    }
    failure:^(NSURLSessionDataTask *task __unused, NSError *error) {
        TNDRCallBlockIfNotNil(completion)(nil, error);
    }];
}

