const int TRIPS_PER_HOUR = 60;
// 用于表示电梯的结构体
struct Elevator {
  int currentFloor;
  int destinationFloor;
  bool isMoving;
};
int main() {
  // 创建电梯
  std::vector<Elevator> elevators;
  for (int i = 0; i < NUM_ELEVATORS; i++) {
    Elevator e;
    e.currentFloor = 1;
    e.destinationFloor = 1;
    e.isMoving = false;
    elevators.push_back(e);
  }
  // 创建用于生成随机楼层请求的随机数生成器
  std::random_device rd;
  std::mt19937 gen(rd());
  std::uniform_int_distribution<> dis(1, NUM_FLOORS);
  // 初始化变量以跟踪总等待时间和行程数
  int totalWaitTime = 0;
  int numTrips = 0;
  // 模拟电梯行程一个小时
  for (int t = 0; t < TRIPS_PER_HOUR; t++) {
    // 生成随机楼层请求
    int requestedFloor = dis(gen);
    // 找到将首先到达请求楼层的电梯
    int minTime = INT_MAX;
    int chosenElevator = -1;
    for (int i = 0; i < NUM_ELEVATORS; i++) {
      Elevator e = elevators[i];
      if (e.isMoving) {
        // 计算此电梯到达请求楼层所需的时间
        int time = std::abs(e.currentFloor - requestedFloor);
        if (time < minTime) {
          minTime = time;
          chosenElevator = i;
        }
      } else {
        // 如果电梯未移动，则可以立即到达请求楼层
        minTime = 0;
        chosenElevator = i;
        break;
      }
    }
    // 更新所选电梯的目标楼层并将isMoving设置为true
    elevators[chosenElevator].destinationFloor = requestedFloor;
    elevators[chosenElevator].isMoving = true;
    // 更新总等待时间和行程数
    totalWaitTime += minTime;
    numTrips++;
  }
  // 计算并输出平均等待时间
  double avgWaitTime = (double)totalWaitTime / numTrips;
  std::cout << "平均等待时间：" << avgWaitTime << std::endl;
  return 0;
}
```
此代码使用向量存储电梯，并使用结构体表示每个电梯。它使用随机数生成器模拟居民请求楼层的情况。

