```
class DraggableWidget {
  constructor(canvas, widgetSize, thumbSize, initialThumbPosition, onMoveStart, onMove, onMoveEnd) {
    this.canvas = canvas;
    this.widgetSize = widgetSize;
    this.thumbSize = thumbSize;
    this.thumbPosition = initialThumbPosition;
    this.onMoveStart = onMoveStart;
    this.onMove = onMove;
    this.onMoveEnd = onMoveEnd;
    this.isDragging = false;
    this.canvas.addEventListener('mousedown', this.handleMouseDown.bind(this));
    this.canvas.addEventListener('mousemove', this.handleMouseMove.bind(this));
    this.canvas.addEventListener('mouseup', this.handleMouseUp.bind(this));
    this.canvas.addEventListener('mouseleave', this.handleMouseLeave.bind(this));
    this.draw();
  }
  handleMouseDown(event) {
    const { x, y } = this.getCursorPosition(event);
    if (this.isCursorOnThumb(x, y)) {
      this.isDragging = true;
    } else {
      this.isDragging = false;
      this.thumbPosition = this.getCenteredThumbPosition(x, y);
      this.draw();
    }
    this.onMoveStart(this.thumbPosition);
  }
  handleMouseMove(event) {
    if (this.isDragging) {
      const { x, y } = this.getCursorPosition(event);
      const newPosition = this.calculateNewThumbPosition(x, y);
      this.updateThumbPosition(newPosition);
      this.draw();
      this.onMove(newPosition);
    }
  }
  handleMouseUp() {
    this.isDragging = false;
    this.onMoveEnd(this.thumbPosition);
  }
  handleMouseLeave() {
    if (this.isDragging) {
      this.isDragging = false;
      this.onMoveEnd(this.thumbPosition);
    }
  }
  getCursorPosition(event) {
    const rect = this.canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    return { x, y };
  }
  isCursorOnThumb(x, y) {
    const [thumbX, thumbY] = this.thumbPosition;
    return (
      x >= thumbX && x <= thumbX + this.thumbSize[0] &&
      y >= thumbY && y <= thumbY + this.thumbSize[1]
    );
  }
  getCenteredThumbPosition(x, y) {
    const centerX = x - this.thumbSize[0] / 2;
    const centerY = y - this.thumbSize[1] / 2;
    return [centerX, centerY];
  }
  calculateNewThumbPosition(x, y) {
    const [thumbX, thumbY] = this.thumbPosition;
    const newX = x - this.thumbSize[0] / 2;
    const newY = y - this.thumbSize[1] / 2;
    const [widgetWidth, widgetHeight] = this.widgetSize;
    const maxX = widgetWidth - this.thumbSize[0];
    const maxY = widgetHeight - this.thumbSize[1];
    return [Math.min(Math.max(newX, 0), maxX), Math.min(Math.max(newY, 0), maxY)];
  }
  updateThumbPosition(newPosition) {
    this.thumbPosition = newPosition;
  }
  draw() {
    const context = this.canvas.getContext('2d');
    const [widgetWidth, widgetHeight] = this.widgetSize;
    const [thumbX, thumbY] = this.thumbPosition;
    context.clearRect(0, 0, widgetWidth, widgetHeight);
    context.fillStyle = 'rgba(0, 0, 0, 0.5)';
    context.fillRect(thumbX, thumbY, this.thumbSize[0], this.thumbSize[1]);
    context.strokeRect(0, 0, widgetWidth, widgetHeight);
  }
  getPosition() {
    return this.thumbPosition;
  }
}
```

