        sum = 0;
        avg_STD[i][0] = avg;
        for(int j = 0; j < 4; j++)
            sum += pow(score[i][j] - avg, 2);
        STD = sqrt(sum/4);
        avg_STD[i][1] = STD;
    }
    printf("------------------------------------------\n");
    printf("姓名  羽球  音樂  棒球  足球  平均  標準差\n");
    for(int i = 0; i < 5; i++){
        printf("%s",name[i]);
        for(int j = 0; j < 4; j++)
            printf("%d ",score[i][j]);
        printf("%.2f  %.2f\n", avg_STD[i][0], avg_STD[i][1]);
    }
    printf("------------------------------------------\n");
    return 0;
}

