要在NestJS中使用Kafka，您需要安装`@nestjs/microservices`包和`kafka-node`包。以下是如何在NestJS中创建Kafka消费者的示例：
```
import { Controller, Get } from '@nestjs/common';
import { ClientKafka } from '@nestjs/microservices';
@Controller()
export class KafkaController {
  constructor(private readonly clientKafka: ClientKafka) {
    this.clientKafka.connect();
  }
  @Get()
  async listen() {
    this.clientKafka.subscribeToResponseOf('test')
      .subscribe(data => {
        console.log(data);
      });
  }
}
```
以下是如何在NestJS中创建Kafka生产者的示例：
```
import { Injectable } from '@nestjs/common';
import { ClientKafka } from '@nestjs/microservices';
@Injectable()
export class KafkaProducer {
  constructor(private readonly clientKafka: ClientKafka) {}
  sendMessage(message: string) {
    this.clientKafka
      .emit('test', message)
      .catch(err => console.error(err));
  }
}
```
